func Parse(args []string) (Command, error) {
	command := Command{Flags: map[string]string{}, used: map[string]bool{}}
	var path []string
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if !strings.HasPrefix(arg, "--") {
			if len(command.Flags) > 0 || command.All {
				return Command{}, fmt.Errorf("positional OCI argument %q follows a flag", arg)
			}
			path = append(path, arg)
			continue
		}
		name := strings.TrimPrefix(arg, "--")
		if name == "all" {
			command.All = true
			continue
		}
		if i+1 >= len(args) || strings.HasPrefix(args[i+1], "--") {
			return Command{}, fmt.Errorf("OCI flag --%s has no value", name)
		}
		if _, repeated := command.Flags[name]; repeated {
			return Command{}, fmt.Errorf("OCI flag --%s is repeated", name)
		}
		command.Flags[name] = args[i+1]
		i++
	}
	command.Path = strings.Join(path, " ")
	return command, nil
}

// value returns a flag's value, or "", and records that it was read.
func (c Command) value(name string) string {
	if c.used != nil {
		c.used[name] = true
	}
	return c.Flags[name]
}

// unused lists the flags no handler read, in sorted order.
func (c Command) unused() []string {
	var names []string
	for name := range c.Flags {
		if !c.used[name] {
			names = append(names, name)
		}
	}
	slices.Sort(names)
	return names
}

func (c Command) flag(name string) (string, error) {
	value := c.value(name)
	if value == "" {
		return "", fmt.Errorf("OCI %s requires --%s", c.Path, name)
	}
	return value, nil
}

// optional returns a pointer to a present flag value, or nil.
func (c Command) optional(name string) *string {
	if value := c.value(name); value != "" {
		return &value
	}
	return nil
}

type Client struct {
	factory *ociclient.Factory
	// endpoint overrides every service host; tests point it at a fake.
	endpoint string
}

// NewClient shares the authenticated provider, rate limits and retry policy of factory.
func NewClient(factory *ociclient.Factory, endpoint string) *Client {
	return &Client{factory: factory, endpoint: endpoint}
}

// Factory is the shared rate-limited factory this client reads through.
func (c *Client) Factory() *ociclient.Factory { return c.factory }

func (c *Client) pin(client *common.BaseClient) {
	client.HTTPClient = strictResponses{next: client.HTTPClient}
	ociclient.ConfigureRequestCancellation(client)
	if c.endpoint != "" {
		client.Host = c.endpoint
	}
}

// Strict decoding keeps ambiguous or truncated provider documents out of inventory.
type strictResponses struct{ next common.HTTPRequestDispatcher }

func (d strictResponses) Do(request *http.Request) (*http.Response, error) {
	response, err := d.next.Do(request)
	if err != nil || response == nil || request.Method == http.MethodHead || response.StatusCode < 200 || response.StatusCode >= 300 {
		return response, err
	}
	const limit = 32 << 20
	wire, err := io.ReadAll(io.LimitReader(response.Body, limit+1))
	response.Body.Close()
	if err != nil {
		return nil, fmt.Errorf("read OCI response: %w", err)
	}
	if len(wire) > limit {
		return nil, errors.New("OCI response exceeds 32 MiB")
	}
	var value any
	if err := json.Unmarshal(wire, &value); err != nil {
		return nil, fmt.Errorf("invalid OCI response: %w", err)
	}
	response.Body = io.NopCloser(bytes.NewReader(wire))
	return response, nil
}

func (c *Client) Call(ctx context.Context, args []string) (data jsontext.Value, handled bool, err error) {
	command, err := Parse(args)
	if err != nil {
		return nil, false, err
	}
	if _, ok := command.Flags["output"]; ok {
		return nil, false, errors.New("OCI --output is fixed to json")
	}
	if _, ok := command.Flags["region"]; ok {
		return nil, false, errors.New("OCI --region is selected by the caller")
	}
	handler, ok := handlers[command.Path]
	if !ok {
		return nil, false, fmt.Errorf("%w: %s", ErrUnsupported, command.Path)
	}
	value, err := handler(ociclient.RequestContext(ctx), c, command)
	if err != nil {
		return nil, true, fmt.Errorf("OCI read failed: %s: %w", command.Path, err)
	}
	if unused := command.unused(); len(unused) > 0 {
		// The read ignored a flag, so its result may be wider than asked
		// for. Report the command as unsupported rather than answer it.
		return nil, false, fmt.Errorf("%w: %s with --%s", ErrUnsupported, command.Path, strings.Join(unused, ", --"))
	}
	data, err = Render(value)
	return data, true, err
}

func Render(value any) (jsontext.Value, error) {
	wire, err := json.Marshal(value, json.FormatNilSliceAsNull(true))
	if err != nil {
		return nil, fmt.Errorf("encode OCI response: %w", err)
	}
	return kebab(jsontext.Value(wire), false)
}

// userKeyed are SDK members whose object keys are user data, not schema.
var userKeyed = map[string]bool{
	"freeformTags": true, "definedTags": true, "systemTags": true, "metadata": true, "extendedMetadata": true,
	"securityAttributes": true, "schemaData": true, "opcMeta": true, "lockedAttributes": true,
}

// nameKeyed are SDK members keyed by user-defined resource names (an NLB's
// backend sets and listeners, a load balancer's named sets) whose values are
// still schema objects: only the immediate keys are preserved, so a listener's
// default-backend-set-name keeps resolving to its backend set.
var nameKeyed = map[string]bool{
	"backendSets": true, "listeners": true, "certificates": true, "hostnames": true,
	"pathRouteSets": true, "ruleSets": true, "routingPolicies": true, "sslCipherSuites": true,
}

func kebab(value jsontext.Value, preserveKeys bool) (jsontext.Value, error) {
	switch value.Kind() {
	case '{':
		var typed map[string]jsontext.Value
		if err := json.Unmarshal(value, &typed); err != nil {
			return nil, err
		}
		result := make(map[string]jsontext.Value, len(typed))
		for key, member := range typed {
			name := key
			if !preserveKeys {
				name = Kebab(key)
			}
			if member.Kind() == '{' && !preserveKeys && nameKeyed[key] {
				var named map[string]jsontext.Value
				if err := json.Unmarshal(member, &named); err != nil {
					return nil, err
				}
				entries := make(map[string]jsontext.Value, len(named))
				for entryName, entry := range named {
					converted, err := kebab(entry, false)
					if err != nil {
						return nil, err
					}
					entries[entryName] = converted
				}
				encoded, err := json.Marshal(entries, json.Deterministic(true))
				if err != nil {
					return nil, err
				}
				result[name] = encoded
				continue
			}
			// The members of a user-keyed map are user data at any depth
			// (defined tags nest one level), so preserve keys below it.
			converted, err := kebab(member, preserveKeys || userKeyed[key])
			if err != nil {
				return nil, err
			}
			result[name] = converted
		}
		wire, err := json.Marshal(result, json.Deterministic(true))
		return jsontext.Value(wire), err
	case '[':
		var typed []jsontext.Value
		if err := json.Unmarshal(value, &typed); err != nil {
			return nil, err
		}
		result := make([]jsontext.Value, len(typed))
		for index, member := range typed {
			converted, err := kebab(member, preserveKeys)
			if err != nil {
				return nil, err
			}
			result[index] = converted
		}
		wire, err := json.Marshal(result)
		return jsontext.Value(wire), err
	default:
		return value, nil
	}
}

// Kebab converts an SDK camelCase member name to the CLI's kebab-case. A run
// of capitals stays one word ("sizeInGBs" -> "size-in-gbs", "vpusPerGB" ->
// "vpus-per-gb"), matching the Python SDK attribute names.
func Kebab(name string) string {
	var out strings.Builder
	runes := []rune(name)
	for index, r := range runes {
		if unicode.IsUpper(r) && index > 0 {
			previous := runes[index-1]
			if unicode.IsLower(previous) || unicode.IsDigit(previous) {
				out.WriteByte('-')
			}
		}
		out.WriteRune(unicode.ToLower(r))
	}
	return out.String()
}

func pages[T any](all bool, fetch func(page *string) ([]T, *string, error)) ([]T, error) {
	var items []T
	var page *string
	for range 256 {
		batch, next, err := fetch(page)
		if err != nil {
			return nil, err
		}
		items = append(items, batch...)
		if !all || next == nil || *next == "" {
			if items == nil {
				items = []T{}
			}
			return items, nil
		}
		page = next
	}
	return nil, errors.New("OCI list exceeds its page bound")
}

func networkGet[T any](flag string, read func(context.Context, core.VirtualNetworkClient, string) (T, error)) handler {
	return func(ctx context.Context, c *Client, command Command) (any, error) {
		id, err := command.flag(flag)
		if err != nil {
			return nil, err
		}
		client, err := c.network()
		if err != nil {
			return nil, err
		}
		return read(ctx, client, id)
	}
}

var (
	networkVcnGet = networkGet("vcn-id", func(ctx context.Context, client core.VirtualNetworkClient, id string) (core.Vcn, error) {
		response, err := client.GetVcn(ctx, core.GetVcnRequest{VcnId: &id})
		return response.Vcn, err
	})
	networkSubnetGet = networkGet("subnet-id", func(ctx context.Context, client core.VirtualNetworkClient, id string) (core.Subnet, error) {
		response, err := client.GetSubnet(ctx, core.GetSubnetRequest{SubnetId: &id})
		return response.Subnet, err
	})

func nlbGet(ctx context.Context, c *Client, command Command) (any, error) {
	id, err := command.flag("network-load-balancer-id")
	if err != nil {
		return nil, err
	}
	client, err := c.factory.NetworkLoadBalancer()
	if err != nil {
		return nil, err
	}
	c.pin(&client.BaseClient)
	response, err := client.GetNetworkLoadBalancer(ctx, networkloadbalancer.GetNetworkLoadBalancerRequest{NetworkLoadBalancerId: &id})
	return response.NetworkLoadBalancer, err
}

func kmsKeyGet(ctx context.Context, c *Client, command Command) (any, error) {
	id, err := command.flag("key-id")
	if err != nil {
		return nil, err
	}
	endpoint, err := command.flag("endpoint")
	if err != nil {
		return nil, err
	}
	client, err := c.KMSManagement(endpoint)
	if err != nil {
		return nil, err
	}
	response, err := client.GetKey(ctx, keymanagement.GetKeyRequest{KeyId: &id})
	return response.Key, err
}

// KMSManagement is the KMS management client of one vault endpoint, which
// must be in the client's region.
func (c *Client) KMSManagement(endpoint string) (keymanagement.KmsManagementClient, error) {
	if !kmsEndpointInRegion(endpoint, c.factory.Region()) {
		return keymanagement.KmsManagementClient{}, fmt.Errorf("KMS management endpoint %q is outside region %s", endpoint, c.factory.Region())
	}
	client, err := keymanagement.NewKmsManagementClientWithConfigurationProvider(c.factory.Provider(), endpoint)
	if err != nil {
		return client, fmt.Errorf("create OCI KMS management client: %w", err)
	}
	c.factory.Configure(&client.BaseClient, ociclient.ServiceKMS)
	c.pin(&client.BaseClient)
	return client, nil
}

func kmsEndpointInRegion(endpoint, region string) bool {
	parsed, err := url.Parse(endpoint)
	if err != nil || parsed.Scheme != "https" || parsed.User != nil || parsed.Port() != "" ||
		(parsed.Path != "" && parsed.Path != "/") || parsed.RawQuery != "" || parsed.Fragment != "" {
		return false
	}
	// OCI vault endpoints are <vault>-management.kms.<region>.oraclecloud.com
	// and <vault>-crypto.kms.<region>.oraclecloud.com; the dotted
	// <vault>.management.<region> and the oci.oraclecloud.com realm domain
	// are accepted too. Every form stays a single label under an Oracle
	// domain pinned to region.
	host := parsed.Hostname()
	for _, domain := range []string{".kms." + region + ".oraclecloud.com", ".kms." + region + ".oci.oraclecloud.com",
		".management." + region + ".oraclecloud.com"} {
		if prefix, ok := strings.CutSuffix(host, domain); ok {
			return prefix != "" && !strings.Contains(prefix, ".")
		}
	}
	return false
}

func osNamespaceGet(ctx context.Context, c *Client, _ Command) (any, error) {
	client, err := c.objects()
	if err != nil {
		return nil, err
	}
	response, err := client.GetNamespace(ctx, objectstorage.GetNamespaceRequest{})
	if err != nil {
		return nil, err
	}
	if response.Value == nil {
		return nil, fmt.Errorf("OCI returned no Object Storage namespace")
	}
	return *response.Value, nil
}

func bucketFlags(command Command) (string, string, error) {
	namespace, err := command.flag("namespace-name")
	if err != nil {
		return "", "", err
	}
	bucket, err := command.flag("bucket-name")
	return namespace, bucket, err
}

func osObjectList(ctx context.Context, c *Client, command Command) (any, error) {
	namespace, bucket, err := bucketFlags(command)
	if err != nil {
		return nil, err
	}
	client, err := c.objects()
	if err != nil {
		return nil, err
	}
	return pages(command.All, func(start *string) ([]objectstorage.ObjectSummary, *string, error) {
		response, err := client.ListObjects(ctx, objectstorage.ListObjectsRequest{NamespaceName: &namespace,
			BucketName: &bucket, Fields: command.optional("fields"), Start: start})
		if err == nil && response.Objects == nil {
			return nil, nil, fmt.Errorf("OCI object list lacks objects")
		}
		return response.Objects, response.NextStartWith, err
	})
}

func osObjectVersionList(ctx context.Context, c *Client, command Command) (any, error) {
	namespace, bucket, err := bucketFlags(command)
	if err != nil {
		return nil, err
	}
	client, err := c.objects()
	if err != nil {
		return nil, err
	}
	// The SDK types ListObjectVersions fields as a single enum value and
	// rejects the comma-separated list the CLI and the API accept, so the
	// list is set on the query before the request is signed.
	if fields := command.value("fields"); fields != "" {
		setQuery(&client.BaseClient, "fields", fields)
	}
	return pages(command.All, func(page *string) ([]objectstorage.ObjectVersionSummary, *string, error) {
		response, err := client.ListObjectVersions(ctx, objectstorage.ListObjectVersionsRequest{NamespaceName: &namespace,
			BucketName: &bucket, Page: page})
		if err == nil && response.Items == nil {
			return nil, nil, fmt.Errorf("OCI object version list lacks items")
		}
		return response.Items, response.OpcNextPage, err
	})
}

// setQuery sets one query parameter on every request the client sends. The
// SDK runs the interceptor before signing, so the parameter is signed.
func setQuery(client *common.BaseClient, name, value string) {
	previous := client.Interceptor
	client.Interceptor = func(request *http.Request) error {
		if previous != nil {
			if err := previous(request); err != nil {
				return err
			}
		}
		query := request.URL.Query()
		query.Set(name, value)
		request.URL.RawQuery = query.Encode()
		return nil
	}
}

// osObjectHead returns the CLI's object head document: the lower-cased
// response headers, which contain no capitals for Render to rewrite.
func osObjectHead(ctx context.Context, c *Client, command Command) (any, error) {
	namespace, bucket, err := bucketFlags(command)
	if err != nil {
		return nil, err
	}
	name, err := command.flag("name")
	if err != nil {
		return nil, err
	}
	client, err := c.objects()
	if err != nil {
		return nil, err
	}
	response, err := client.HeadObject(ctx, objectstorage.HeadObjectRequest{NamespaceName: &namespace, BucketName: &bucket, ObjectName: &name})
	if err != nil {
		if serviceErr, ok := common.IsServiceError(err); ok && serviceErr.GetHTTPStatusCode() == http.StatusNotFound {
			return nil, fmt.Errorf("object %s does not exist", name)
		}
		return nil, err
	}
	headers := map[string]any{}
	if response.RawResponse != nil {
		for key, values := range response.RawResponse.Header {
			if len(values) > 0 {
				headers[strings.ToLower(key)] = values[0]
			}
		}
	}
	return headers, nil
}

func init() {
	for path, h := range map[string]handler{
		"compute shape list": listIn((*Client).compute,
			func(ctx context.Context, client core.ComputeClient, compartment string, command Command, page *string) ([]core.Shape, *string, error) {
				response, err := client.ListShapes(ctx, core.ListShapesRequest{CompartmentId: &compartment,
					ImageId: command.optional("image-id"), AvailabilityDomain: command.optional("availability-domain"), Page: page})
				return response.Items, response.OpcNextPage, err
			}),

		"nlb network-load-balancer list": nlbList,
		"os bucket list":                 osBucketList,
	} {
		handlers[path] = h
	}
}

func listIn[S, T any](service func(*Client) (S, error),
	list func(context.Context, S, string, Command, *string) ([]T, *string, error),
) handler {
	return func(ctx context.Context, c *Client, command Command) (any, error) {
		compartment, err := command.flag("compartment-id")
		if err != nil {
			return nil, err
		}
		client, err := service(c)
		if err != nil {
			return nil, err
		}
		return pages(command.All, func(page *string) ([]T, *string, error) {
			return list(ctx, client, compartment, command, page)
		})
	}
}

func nlbList(ctx context.Context, c *Client, command Command) (any, error) {
	compartment, err := command.flag("compartment-id")
	if err != nil {
		return nil, err
	}
	client, err := c.factory.NetworkLoadBalancer()
	if err != nil {
		return nil, err
	}
	c.pin(&client.BaseClient)
	items, err := pages(command.All, func(page *string) ([]networkloadbalancer.NetworkLoadBalancerSummary, *string, error) {
		response, err := client.ListNetworkLoadBalancers(ctx, networkloadbalancer.ListNetworkLoadBalancersRequest{
			CompartmentId: &compartment, Page: page})
		return response.Items, response.OpcNextPage, err
	})
	if err != nil {
		return nil, err
	}
	return map[string]any{"items": items}, nil
}

