func Run(ctx context.Context, args []string, out io.Writer) error {
	fs := flag.NewFlagSet("oci-region teardown", flag.ContinueOnError)
	fs.SetOutput(out)
	planPath := fs.String("plan", "", "reviewed teardown plan JSON")
	apply := fs.Bool("apply", false, "delete; without it only print the diff")
	if err := fs.Parse(args); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			return nil
		}
		return err
	}
	if fs.NArg() != 0 || *planPath == "" {
		return errors.New("usage: ts-orch oci-region teardown --plan FILE [--apply]")
	}
	b, err := os.ReadFile(*planPath)
	if err != nil {
		return err
	}
	var plan Plan
	if err := json.Unmarshal(b, &plan, json.RejectUnknownMembers(true)); err != nil {
		return fmt.Errorf("teardown plan: %w", err)
	}
	if err := plan.Validate(); err != nil {
		return err
	}
	provider, err := NewSDKProvider(ctx, plan.Region)
	if err != nil {
		return err
	}
	return provider.teardown(ctx, plan, *apply, out)
}

func (p Plan) Validate() error {
	if p.Cell == "" || !catalog.IsOCIRegion(p.Region) {
		return fmt.Errorf("teardown plan needs a cell and a catalog OCI region, got %q/%q", p.Cell, p.Region)
	}
	deleted, owned := map[string]bool{}, map[string]bool{}
	for _, r := range p.Delete {
		if !slices.Contains(Kinds, r.Kind) || r.ID == "" || r.Name == "" || r.Compartment == "" ||
			(r.Kind == "kms-key") != (r.VaultID != "") {
			return fmt.Errorf("invalid teardown resource %+v", r)
		}
		if deleted[r.ID] {
			return fmt.Errorf("teardown plan lists %s twice", r.ID)
		}
		deleted[r.ID] = true
		if r.Kind == "compartment" {
			owned[r.ID] = true
		}
	}
	for _, r := range p.Delete {
		if r.Kind != "compartment" && !owned[r.Compartment] {
			return fmt.Errorf("%s %s lives in compartment %s, which the plan does not delete", r.Kind, r.ID, r.Compartment)
		}
	}
	for _, r := range p.Keep {
		if deleted[r.ID] || deleted[r.VaultID] || deleted[r.Compartment] {
			return fmt.Errorf("teardown plan deletes %s or the vault or compartment it needs, but keeps it", r.ID)
		}
	}
	return nil
}

func Teardown(ctx context.Context, plan Plan, provider Provider, apply bool, out io.Writer) error {
	if err := plan.Validate(); err != nil {
		return err
	}
	steps := make([]step, len(plan.Delete))
	verified := map[string]Resource{}
	for i, r := range plan.Delete {
		steps[i].Resource = r
	}
	slices.SortStableFunc(steps, func(a, b step) int {
		return slices.Index(Kinds, a.Kind) - slices.Index(Kinds, b.Kind)
	})
	deletedCompartments := map[string]bool{}
	for i := range steps {
		s := &steps[i]
		o, err := provider.Get(ctx, s.Resource)
		if err != nil {
			return fmt.Errorf("read %s %s: %w", s.Kind, s.ID, err)
		}
		if o.State != NotFound && o.State != "DELETED" && o.State != "TERMINATED" {
			if o.Name != s.Name || o.Compartment != s.Compartment {
				return fmt.Errorf("%s %s is %q in %s, the plan says %q in %s", s.Kind, s.ID, o.Name, o.Compartment, s.Name, s.Compartment)
			}
			verified[s.ID] = s.Resource
		}
		if s.Kind == "compartment" && o.State == "DELETED" {
			deletedCompartments[s.ID] = true
		}
		s.observed = o
	}
	for i := range steps {
		s := &steps[i]
		switch s.observed.State {
		case "DELETED", "TERMINATED":
			s.action = "gone"
		case NotFound:
			s.action = "absent"
			if deletedCompartments[s.Compartment] {
				s.action = "gone"
			}
		case "DELETING", "SCHEDULING_DELETION", "PENDING_DELETION", "TERMINATING":
			s.action = "pending"
			if s.observed.DeleteAt != nil {
				s.detail = "purge " + s.observed.DeleteAt.UTC().Format(time.RFC3339)
			}
		default:
			s.action = "delete"
		}
	}
	// Steps are final before any mutation: a compartment waits for every
	// planned resource inside it, child compartments included.
	for i := range steps {
		s := &steps[i]
		if s.Kind != "compartment" || s.action != "delete" {
			continue
		}
		inside := 0
		for _, c := range steps {
			if c.Compartment == s.ID && c.action != "gone" && c.action != "absent" {
				inside++
			}
		}
		if inside > 0 {
			s.action, s.detail = "held", fmt.Sprintf("waits for %d resources inside it to be gone", inside)
		}
	}
	var blocked []error
	for i := range steps {
		s := &steps[i]
		if s.Kind != "kms-vault" || s.action == "gone" || s.action == "absent" {
			continue
		}
		if err := verifyVaultContents(ctx, provider, s.Resource, verified); err != nil {
			s.action, s.detail = "blocked", err.Error()
			blocked = append(blocked, err)
		}
	}

	mode := "dry run"
	if apply {
		mode = "apply"
	}
	if _, err := fmt.Fprintf(out, "teardown %s %s (%s)\n", plan.Cell, plan.Region, mode); err != nil {
		return err
	}
	counts := map[string]int{}
	for _, s := range steps {
		counts[s.action]++
		if _, err := fmt.Fprintf(out, "%-8s %-12s %s %s %s\n", s.action, s.Kind, s.Name, s.ID, s.detail); err != nil {
			return err
		}
	}
	for _, r := range plan.Keep {
		if _, err := fmt.Fprintf(out, "%-8s %-12s %s %s %s\n", "keep", r.Kind, r.Name, r.ID, r.Reason); err != nil {
			return err
		}
	}
	status := "incomplete"
	if counts["gone"] == len(steps) {
		status = "complete"
	}
	if _, err := fmt.Fprintf(out, "%s: gone %d, absent %d, pending %d, delete %d, held %d, keep %d\n", status,
		counts["gone"], counts["absent"], counts["pending"], counts["delete"], counts["held"], len(plan.Keep)); err != nil {
		return err
	}
	if len(blocked) > 0 {
		if _, err := fmt.Fprintf(out, "blocked: %d vaults; no mutations permitted\n", len(blocked)); err != nil {
			return errors.Join(err, errors.Join(blocked...))
		}
		return errors.Join(blocked...)
	}
	if !apply {
		return nil
	}
	deleted := 0
	for _, s := range steps {
		if s.action != "delete" {
			continue
		}
		if s.Kind == "kms-vault" {
			if err := verifyVaultContents(ctx, provider, s.Resource, verified); err != nil {
				if _, writeErr := fmt.Fprintf(out, "blocked  kms-vault    %s %s %s\n", s.Name, s.ID, err); writeErr != nil {
					return errors.Join(err, writeErr)
				}
				return fmt.Errorf("refuse vault deletion after %d deletions: %w", deleted, err)
			}
		}
		if err := provider.Delete(ctx, s.Resource); err != nil {
			return fmt.Errorf("delete %s %s after %d deletions: %w", s.Kind, s.ID, deleted, err)
		}
		deleted++
		if _, err := fmt.Fprintf(out, "deleted  %-12s %s %s\n", s.Kind, s.Name, s.ID); err != nil {
			return err
		}
	}
	_, err := fmt.Fprintf(out, "applied: deleted %d; rerun to follow pending deletions\n", deleted)
	return err
}

func verifyVaultContents(ctx context.Context, provider Provider, vault Resource, verified map[string]Resource) error {
	contents, err := provider.VaultContents(ctx, vault)
	if err != nil {
		return fmt.Errorf("list vault %s: %w", vault.ID, err)
	}
	var unexpected []error
	for _, live := range contents {
		inventory, ok := verified[live.ID]
		if !ok || (live.Kind != "kms-key" && live.Kind != "vault-secret") || live.Kind != inventory.Kind ||
			live.Name != inventory.Name || live.Compartment != inventory.Compartment || live.VaultID != vault.ID ||
			(live.Kind == "kms-key" && inventory.VaultID != vault.ID) {
			unexpected = append(unexpected, fmt.Errorf("vault %s has unexpected %s %s %q in compartment %s (vault %s); not verified as cell-owned by the inventory",
				vault.ID, live.Kind, live.ID, live.Name, live.Compartment, live.VaultID))
		}
	}
	return errors.Join(unexpected...)
}

func (p *SDKProvider) useHomeIdentity(ctx context.Context) error {
	tenancy, err := p.factory.Provider().TenancyOCID()
	if err != nil {
		return err
	}
	if tenancy == "" {
		return fmt.Errorf("OCI configuration has no tenancy")
	}
	lookup, cancel := context.WithTimeout(ctx, 30*time.Second)
	defer cancel()
	response, err := p.identity.ListRegionSubscriptions(lookup, identity.ListRegionSubscriptionsRequest{TenancyId: &tenancy})
	if err != nil {
		return fmt.Errorf("read the tenancy home region: %w", err)
	}
	home := ""
	for _, subscription := range response.Items {
		if subscription.IsHomeRegion == nil || !*subscription.IsHomeRegion {
			continue
		}
		region := deref(subscription.RegionName)
		if home != "" || !catalog.IsOCIRegion(region) || subscription.Status != identity.RegionSubscriptionStatusReady {
			return fmt.Errorf("invalid or ambiguous home-region subscription %q", region)
		}
		home = region
	}
	if home == "" {
		return fmt.Errorf("region subscriptions do not identify a home region")
	}
	p.identity.SetRegion(home)
	return nil
}

func (p *SDKProvider) Get(ctx context.Context, r Resource) (Observed, error) {
	var o Observed
	var err error
	switch r.Kind {
	case "vault-secret":
		var resp vault.GetSecretResponse
		resp, err = p.secrets.GetSecret(ctx, vault.GetSecretRequest{SecretId: &r.ID})
		s := resp.Secret
		o = Observed{deref(s.SecretName), deref(s.CompartmentId), string(s.LifecycleState), sdkTime(s.TimeOfDeletion)}
	case "kms-vault":
		var resp keymanagement.GetVaultResponse
		resp, err = p.vaults.GetVault(ctx, keymanagement.GetVaultRequest{VaultId: &r.ID})
		v := resp.Vault
		o = Observed{deref(v.DisplayName), deref(v.CompartmentId), string(v.LifecycleState), sdkTime(v.TimeOfDeletion)}
	case "kms-key":
		var keys *keymanagement.KmsManagementClient
		var vaultState string
		if keys, vaultState, err = p.keys(ctx, r.VaultID); err == nil && keys == nil {
			return Observed{State: vaultState}, nil
		}
		if err == nil {
			var resp keymanagement.GetKeyResponse
			resp, err = keys.GetKey(ctx, keymanagement.GetKeyRequest{KeyId: &r.ID})
			k := resp.Key
			o = Observed{deref(k.DisplayName), deref(k.CompartmentId), string(k.LifecycleState), sdkTime(k.TimeOfDeletion)}
		}
	case "compartment":
		var resp identity.GetCompartmentResponse
		resp, err = p.identity.GetCompartment(ctx, identity.GetCompartmentRequest{CompartmentId: &r.ID})
		c := resp.Compartment
		o = Observed{Name: deref(c.Name), Compartment: deref(c.CompartmentId), State: string(c.LifecycleState)}
	default:
		return o, fmt.Errorf("unsupported kind %q", r.Kind)
	}
	if notFound(err) {
		return Observed{State: NotFound}, nil
	}
	return o, err
}

func (p *SDKProvider) Delete(ctx context.Context, r Resource) error {
	switch r.Kind {
	case "vault-secret":
		_, err := p.secrets.ScheduleSecretDeletion(ctx, vault.ScheduleSecretDeletionRequest{SecretId: &r.ID,
			ScheduleSecretDeletionDetails: vault.ScheduleSecretDeletionDetails{TimeOfDeletion: after(secretWindow)}})
		return err
	case "kms-vault":
		_, err := p.vaults.ScheduleVaultDeletion(ctx, keymanagement.ScheduleVaultDeletionRequest{VaultId: &r.ID,
			ScheduleVaultDeletionDetails: keymanagement.ScheduleVaultDeletionDetails{TimeOfDeletion: after(keyWindow)}})
		return err
	case "kms-key":
		keys, state, err := p.keys(ctx, r.VaultID)
		if err != nil {
			return err
		}
		if keys == nil {
			return fmt.Errorf("cannot schedule key %s: vault %s is %s", r.ID, r.VaultID, state)
		}
		_, err = keys.ScheduleKeyDeletion(ctx, keymanagement.ScheduleKeyDeletionRequest{KeyId: &r.ID,
			ScheduleKeyDeletionDetails: keymanagement.ScheduleKeyDeletionDetails{TimeOfDeletion: after(keyWindow)}})
		return err
	case "compartment":
		_, err := p.identity.DeleteCompartment(ctx, identity.DeleteCompartmentRequest{CompartmentId: &r.ID})
		return err
	}
	return fmt.Errorf("unsupported kind %q", r.Kind)
}

// keys returns a management client for a vault's keys. Without a vault it
// returns nil and the state its keys share: DELETED with a deleted vault,
// NotFound when OCI answers 404 for the vault.
func (p *SDKProvider) keys(ctx context.Context, vaultID string) (*keymanagement.KmsManagementClient, string, error) {
	resp, err := p.vaults.GetVault(ctx, keymanagement.GetVaultRequest{VaultId: &vaultID})
	if notFound(err) {
		return nil, NotFound, nil
	}
	if err != nil {
		return nil, "", err
	}
	if resp.LifecycleState == keymanagement.VaultLifecycleStateDeleted {
		return nil, "DELETED", nil
	}
	client, err := keymanagement.NewKmsManagementClientWithConfigurationProvider(p.factory.Provider(), deref(resp.ManagementEndpoint))
	if err != nil {
		return nil, "", err
	}
	p.factory.Configure(&client.BaseClient, ociclient.ServiceKMS)
	return &client, "", nil

func (p *SDKProvider) VaultContents(ctx context.Context, r Resource) ([]Resource, error) {
	keys, state, err := p.keys(ctx, r.ID)
	if err != nil {
		return nil, err
	}
	if keys == nil {
		if state == "DELETED" {
			return nil, nil
		}
		return nil, fmt.Errorf("cannot verify contents of vault %s: %s", r.ID, state)
	}
	tenancy, err := p.factory.Provider().TenancyOCID()
	if err != nil {
		return nil, err
	}
	compartments := []string{tenancy}
	var page *string
	for {
		resp, err := p.identity.ListCompartments(ctx, identity.ListCompartmentsRequest{CompartmentId: &tenancy,
			CompartmentIdInSubtree: common.Bool(true), AccessLevel: identity.ListCompartmentsAccessLevelAny, Page: page})
		if err != nil {
			return nil, err
		}
		for _, c := range resp.Items {
			if c.LifecycleState != identity.CompartmentLifecycleStateDeleted {
				compartments = append(compartments, deref(c.Id))
			}
		}
		if page = resp.OpcNextPage; page == nil {
			break
		}
	}
	var contents []Resource
	for _, compartment := range compartments {
		for page = nil; ; {
			resp, err := keys.ListKeys(ctx, keymanagement.ListKeysRequest{CompartmentId: &compartment, Page: page})
			if err != nil {
				return nil, err
			}
			for _, k := range resp.Items {
				if k.LifecycleState != keymanagement.KeySummaryLifecycleStateDeleted {
					contents = append(contents, Resource{Kind: "kms-key", ID: deref(k.Id), Name: deref(k.DisplayName),
						Compartment: deref(k.CompartmentId), VaultID: deref(k.VaultId)})
				}
			}
			if page = resp.OpcNextPage; page == nil {
				break
			}
		}
		for page = nil; ; {
			resp, err := p.secrets.ListSecrets(ctx, vault.ListSecretsRequest{CompartmentId: &compartment, VaultId: &r.ID, Page: page})
			if err != nil {
				return nil, err
			}
			for _, s := range resp.Items {
				if s.LifecycleState != vault.SecretSummaryLifecycleStateDeleted {
					contents = append(contents, Resource{Kind: "vault-secret", ID: deref(s.Id), Name: deref(s.SecretName),
						Compartment: deref(s.CompartmentId), VaultID: deref(s.VaultId)})
				}
			}
			if page = resp.OpcNextPage; page == nil {
				break
			}
		}
	}
	return contents, nil
}

func notFound(err error) bool {
	failure, ok := common.IsServiceError(err)
	return ok && failure.GetHTTPStatusCode() == http.StatusNotFound
}

func deref(s *string) string {
	if s == nil {
		return ""
	}
	return *s
}

func sdkTime(t *common.SDKTime) *time.Time {
	if t == nil {
		return nil
	}
	return &t.Time
}

func after(d time.Duration) *common.SDKTime {
	return &common.SDKTime{Time: time.Now().Add(d)}
}

func IsOCIRegion(region string) bool {
	_, ok := CellForOCIRegion(region)
	return ok
}

// CellForOCIRegion maps an exact OCI region identifier back to its cell.
func CellForOCIRegion(region string) (Entry, bool) {
	for _, entry := range entries {
		if entry.OCIRegion == region {
			return entry, true
		}
	}
	return Entry{}, false
}

