type netBirdTeardownHTTP struct {
	next     http.RoundTripper
	endpoint *url.URL
}

func (transport netBirdTeardownHTTP) RoundTrip(request *http.Request) (*http.Response, error) {
	copy := request.Clone(request.Context())
	copy.URL.Scheme, copy.URL.Host = transport.endpoint.Scheme, transport.endpoint.Host
	return transport.next.RoundTrip(copy)
}

func (p *SDKProvider) teardown(ctx context.Context, plan Plan, apply bool, out io.Writer) error {
	if err := plan.Validate(); err != nil {
		return err
	}
	if plan.Region != "sa-saopaulo-1" {
		return Teardown(ctx, plan, p, apply, out)
	}
	resolver, err := region.DiscoverCurrentFoundation(ctx, p.factory)
	if err != nil {
		return fmt.Errorf("GRU teardown blocked: current foundation authority: %w", err)
	}
	view, err := region.ObserveNetBirdNetworkTeardown(ctx, p.factory, resolver)
	if err != nil {
		return fmt.Errorf("GRU teardown blocked: NetBird network provenance: %w", err)
	}
	if err := view.CheckProvenance(ctx); err != nil {
		return fmt.Errorf("GRU teardown blocked: NetBird network provenance changed: %w", err)
	}
	if _, err := fmt.Fprintf(out, "NetBird network inventory: operation %s generation %d instance %s observed %s\n", view.OperationID(), view.Generation(), view.InstanceID(), view.ObservedAt().Format(time.RFC3339)); err != nil {
		return err
	}
	for _, resource := range view.Resources() {
		if _, err := fmt.Fprintf(out, "%-8s %-24s %s compartment %s\n", "retain", resource.Kind, resource.ID, resource.CompartmentID); err != nil {
			return err
		}
	}
	for _, resource := range view.Keep() {
		if _, err := fmt.Fprintf(out, "%-8s %-24s %s compartment %s\n", "keep", resource.Kind, resource.ID, resource.CompartmentID); err != nil {
			return err
		}
	}
	blocked := []error{errors.New("GRU teardown has no verified manager retirement and protected-backup destructive authority")}
	for _, reason := range view.Blockers() {
		blocked = append(blocked, errors.New(reason))
		if _, err := fmt.Fprintf(out, "blocked: %s\n", reason); err != nil {
			return errors.Join(err, errors.Join(blocked...))
		}
	}
	return errors.Join(blocked...)
}

func DiscoverCurrentFoundation(ctx context.Context, factory *ociclient.Factory) (FoundationResolver, error) {
	genesis, err := trust.DiscoveryGenesis()
	if err != nil {
		return FoundationResolver{}, err
	}
	client, tenancy, err := foundationHomeClient(factory)
	if err != nil {
		return FoundationResolver{}, err
	}
	resolver, err := discoverCurrentFoundation(ctx, client, tenancy, genesis)
	if err == nil {
		resolver.Footprint.(*SignedFootprint).factory = factory
	}
	return resolver, err
}

func discoverCurrentFoundation(ctx context.Context, client foundationDiscoveryObjects, tenancy string, genesis trust.Keyring) (FoundationResolver, error) {
	resolver, _, err := resolveCurrentFoundation(ctx, client, tenancy, genesis, nil)
	return resolver, err
}

func resolveCurrentFoundation(ctx context.Context, client foundationDiscoveryObjects, tenancy string, genesis trust.Keyring, retained *RetainedFoundation) (FoundationResolver, RetainedFoundation, error) {
	if len(genesis) == 0 || tenancy == "" {
		return FoundationResolver{}, RetainedFoundation{}, errors.New("current foundation requires independent genesis and authenticated tenancy")
	}
	directory, err := openFoundationFloorDirectory()
	if err != nil {
		return FoundationResolver{}, RetainedFoundation{}, fmt.Errorf("open foundation trust floor: %w", err)
	}
	defer directory.Close()
	digest := sha256.Sum256([]byte(tenancy))
	name := hex.EncodeToString(digest[:]) + ".json"
	lock, err := openFoundationFloorFile(int(directory.Fd()), name+".lock", unix.O_RDWR|unix.O_CREAT)
	if err != nil {
		return FoundationResolver{}, RetainedFoundation{}, err
	}
	defer lock.Close()
	for {
		if err := ctx.Err(); err != nil {
			return FoundationResolver{}, RetainedFoundation{}, err
		}
		err = unix.Flock(int(lock.Fd()), unix.LOCK_EX|unix.LOCK_NB)
		if err == nil {
			break
		}
		if !errors.Is(err, unix.EWOULDBLOCK) && !errors.Is(err, unix.EINTR) {
			return FoundationResolver{}, RetainedFoundation{}, err
		}
		select {
		case <-ctx.Done():
			return FoundationResolver{}, RetainedFoundation{}, ctx.Err()
		case <-time.After(20 * time.Millisecond):
		}
	}
	defer unix.Flock(int(lock.Fd()), unix.LOCK_UN)
	previous, found, err := readFoundationFloor(int(directory.Fd()), name, tenancy, genesis)
	if err != nil {
		return FoundationResolver{}, RetainedFoundation{}, err
	}
	var snapshot RetainedFoundation
	if retained == nil {
		snapshot, err = readCurrentFoundation(ctx, client, tenancy)
		if err != nil {
			return FoundationResolver{}, RetainedFoundation{}, err
		}
	} else {
		snapshot = retained.clone()
	}
	namespace, anchorWire, chainWire := snapshot.Namespace, snapshot.AnchorWire, snapshot.RootChainWire
	envelope, err := trust.DecodeEnvelope(anchorWire)
	if err != nil {
		return FoundationResolver{}, RetainedFoundation{}, err
	}

func openFoundationFloorDirectory() (*os.File, error) {
	config, err := os.UserConfigDir()
	if err != nil {
		return nil, err
	}
	if !filepath.IsAbs(config) || filepath.Clean(config) != config {
		return nil, errors.New("foundation user config directory must be absolute and clean")
	}
	path := filepath.Join(config, "terrascale-orchestrator", "foundation")
	fd, err := unix.Open("/", unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC, 0)
	if err != nil {
		return nil, err
	}
	parts := strings.Split(strings.TrimPrefix(path, "/"), "/")
	for index, component := range parts {
		next, openErr := unix.Openat(fd, component, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0)
		if errors.Is(openErr, unix.ENOENT) {
			if openErr = unix.Mkdirat(fd, component, 0700); openErr == nil || errors.Is(openErr, unix.EEXIST) {
				openErr = unix.Fsync(fd)
				if openErr == nil {
					next, openErr = unix.Openat(fd, component, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0)
				}
			}
		}
		unix.Close(fd)
		if openErr != nil {
			return nil, openErr
		}
		fd = next
		var stat unix.Stat_t
		if err := unix.Fstat(fd, &stat); err != nil {
			unix.Close(fd)
			return nil, err
		}
		owner := stat.Uid == uint32(os.Geteuid())
		// Root-owned sticky ancestors such as /tmp are safe for private test
		// homes; only the user may own either application directory.
		stickyRoot := stat.Uid == 0 && stat.Mode&unix.S_ISVTX != 0
		if (!owner && stat.Uid != 0) || stat.Mode&0022 != 0 && !stickyRoot ||
			index >= len(parts)-2 && (!owner || stat.Mode&07777 != 0700) {
			unix.Close(fd)
			return nil, errors.New("unsafe foundation floor directory owner or permissions")
		}
	}
	return os.NewFile(uintptr(fd), "foundation floor directory"), nil
}

func openFoundationFloorFile(directory int, name string, flags int) (*os.File, error) {
	fd, err := unix.Openat(directory, name, flags|unix.O_CLOEXEC|unix.O_NOFOLLOW|unix.O_NONBLOCK, 0600)
	if err != nil {
		return nil, err
	}
	file := os.NewFile(uintptr(fd), name)
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil {
		file.Close()
		return nil, err
	}
	if stat.Mode&unix.S_IFMT != unix.S_IFREG || stat.Uid != uint32(os.Geteuid()) || stat.Nlink != 1 || stat.Mode&07777 != 0600 || stat.Size > foundationFloorLimit {
		file.Close()
		return nil, errors.New("unsafe foundation floor file owner, links, mode or length")
	}
	return file, nil
}

func foundationHomeClient(factory *ociclient.Factory) (*objectstorage.ObjectStorageClient, string, error) {
	if factory == nil {
		return nil, "", fmt.Errorf("%w: authenticated OCI caller is absent", ErrFoundationDiscoveryPending)
	}
	tenancy, err := factory.Provider().TenancyOCID()
	if err != nil || tenancy == "" {
		return nil, "", fmt.Errorf("%w: authenticated tenancy is absent", ErrFoundationDiscoveryPending)
	}
	home, err := factory.ForRegion(foundationHomeRegion)
	if err != nil {
		return nil, "", err
	}
	client, err := home.ObjectStorage()
	return &client, tenancy, err
}

func discoveryNamespace(ctx context.Context, client foundationDiscoveryObjects, tenancy string) (string, error) {
	ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()
	response, err := client.GetNamespace(ociclient.RequestContext(ctx), objectstorage.GetNamespaceRequest{CompartmentId: new(tenancy)})
	if err != nil || response.Value == nil || *response.Value == "" || strings.ContainsAny(*response.Value, "/\\\r\n") {
		return "", errors.Join(fmt.Errorf("%w: caller's home storage namespace is unavailable", ErrFoundationDiscoveryPending), err, ctx.Err())
	}
	return *response.Value, nil
}

func readCurrentFoundation(ctx context.Context, client foundationDiscoveryObjects, tenancy string) (RetainedFoundation, error) {
	namespace, err := discoveryNamespace(ctx, client, tenancy)
	if err != nil {
		return RetainedFoundation{}, err
	}
	anchor, err := readDiscoveryObject(ctx, client, namespace, foundationDiscoveryObject, bootstrap.MaxBootstrapAnchorBytes)
	if err != nil {
		return RetainedFoundation{}, fmt.Errorf("%w: read current home anchor: %w", ErrFoundationDiscoveryPending, err)
	}
	chain, err := readDiscoveryObject(ctx, client, namespace, foundationRootChainObject, trust.MaxRootChainBytes)
	if err != nil {
		return RetainedFoundation{}, fmt.Errorf("%w: read current root chain: %w", ErrFoundationDiscoveryPending, err)
	}
	return RetainedFoundation{TenancyID: tenancy, Namespace: namespace, RootChainWire: chain, AnchorWire: anchor}, nil
}
